INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(1,'rahasia-di-balik-sekolah','sejarah','Sekolah yang menyimpan sejarah','Hogwarts menjadi saksi pertemuan kehidupan sekolah dengan konflik dunia sihir.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"sejarah","id":1,"intro":"Hogwarts menjadi saksi pertemuan kehidupan sekolah dengan konflik dunia sihir.","note":"Interpretasi editorial: sekolah menjadi tempat pengetahuan diwariskan, tetapi juga tempat generasi baru mempertanyakan keputusan generasi sebelumnya.","related":["mengenal-hogwarts"],"sections":[{"heading":"Di antara pelajaran dan rahasia","text":"Pembukaan Kamar Rahasia, Turnamen Triwizard dan Pertempuran Hogwarts menunjukkan bagaimana kastil berulang kali berada di pusat peristiwa besar. Membaca Hogwarts sebagai tempat bersejarah berarti memperhatikan siapa yang menguasai ruangnya, rahasia apa yang disimpan, dan bagaimana para murid menghadapi perubahan."}],"slug":"rahasia-di-balik-sekolah","source":{"access_date":"2026-09-14","publisher":"Wizarding World Digital","title":"Sekolah yang menyimpan sejarah — referensi resmi","type":"web","url":"https://www.harrypotter.com/fact-file/locations/hogwarts","verification":"Diperiksa melalui pencarian web"},"status":"published","title":"Sekolah yang menyimpan sejarah"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(1,'Sekolah yang menyimpan sejarah — referensi resmi','','Wizarding World Digital','https://www.harrypotter.com/fact-file/locations/hogwarts','web','2026-09-14','Diperiksa melalui pencarian web') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(1,1) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(2,'mengenal-hogwarts','hogwarts','Hogwarts, lebih dari sebuah kastil','Di balik dinding sekolah, ruang belajar berdampingan dengan lorong dan ruangan tersembunyi.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"hogwarts","id":2,"intro":"Di balik dinding sekolah, ruang belajar berdampingan dengan lorong dan ruangan tersembunyi.","note":"Interpretasi editorial: arsitektur yang sulit ditebak membuat penjelajahan menjadi bagian dari proses belajar. Peta dalam aplikasi ini adalah navigasi editorial, bukan denah resmi.","related":["sidang-harry"],"sections":[{"heading":"Kastil sebagai pengalaman","text":"Hogwarts memiliki 142 tangga. Jalur rahasia dan ruang tersembunyi membuat perjalanan di dalamnya tidak selalu sederhana. Potret-potret sihir membawa kepribadian dan kisah para subjeknya; potret mantan kepala sekolah bahkan dapat memberikan nasihat."}],"slug":"mengenal-hogwarts","source":{"access_date":"2026-09-14","publisher":"Wizarding World Digital","title":"Hogwarts, lebih dari sebuah kastil — referensi resmi","type":"web","url":"https://www.harrypotter.com/features/10-cool-hogwarts-facts-to-impress-your-friends","verification":"Diperiksa melalui pencarian web"},"status":"published","title":"Hogwarts, lebih dari sebuah kastil"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(2,'Hogwarts, lebih dari sebuah kastil — referensi resmi','','Wizarding World Digital','https://www.harrypotter.com/features/10-cool-hogwarts-facts-to-impress-your-friends','web','2026-09-14','Diperiksa melalui pencarian web') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(2,2) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(3,'sidang-harry','kementerian','Ketika Harry berhadapan dengan hukum','Penggunaan sihir di luar sekolah membawa Harry ke dalam proses pemeriksaan Kementerian.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"kementerian","id":3,"intro":"Penggunaan sihir di luar sekolah membawa Harry ke dalam proses pemeriksaan Kementerian.","note":"Interpretasi editorial: membaca adegan sidang membantu membedakan aturan tertulis, bukti, pembelaan dan kepentingan politik. Ini pembahasan fiksi, bukan panduan hukum nyata.","related":["hippogriff"],"sections":[{"heading":"Hukum dan kekuasaan","text":"Dalam Harry Potter and the Order of the Phoenix, Harry menghadapi sidang setelah menggunakan Patronus saat serangan Dementor. Peristiwa ini memperlihatkan jarak antara konteks tindakan seseorang dan cara lembaga menilainya."}],"slug":"sidang-harry","source":{"author":"J. K. Rowling","locator":"Bab 8, The Hearing","title":"Harry Potter and the Order of the Phoenix","type":"book","url":null,"verification":"Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini"},"status":"published","title":"Ketika Harry berhadapan dengan hukum"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(3,'Harry Potter and the Order of the Phoenix','J. K. Rowling','',NULL,'book',NULL,'Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(3,3) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(4,'hippogriff','makhluk','Hippogriff: penghormatan sebelum kedekatan','Pertemuan dengan Buckbeak memperlihatkan bahwa keberanian perlu disertai sikap hormat.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"makhluk","id":4,"intro":"Pertemuan dengan Buckbeak memperlihatkan bahwa keberanian perlu disertai sikap hormat.","note":"Interpretasi editorial: makhluk sihir tidak sekadar menjadi latar petualangan; cara tokoh memperlakukannya juga mengungkap sikap mereka terhadap makhluk lain.","related":["wingardium-leviosa"],"sections":[{"heading":"Pelajaran pertama Hagrid","text":"Hippogriff memadukan ciri elang dan kuda. Dalam pelajaran Pemeliharaan Satwa Gaib, murid diminta menghormati makhluk itu sebelum mendekat. Keberhasilan Harry dan insiden yang dialami Draco memperlihatkan dua hasil berbeda dalam pertemuan yang sama."}],"slug":"hippogriff","source":{"author":"J. K. Rowling","locator":"Bab 6, Talons and Tea Leaves","title":"Harry Potter and the Prisoner of Azkaban","type":"book","url":null,"verification":"Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini"},"status":"published","title":"Hippogriff: penghormatan sebelum kedekatan"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(4,'Harry Potter and the Prisoner of Azkaban','J. K. Rowling','',NULL,'book',NULL,'Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(4,4) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(5,'wingardium-leviosa','grimoire','Wingardium Leviosa','Mantra levitasi memperkenalkan hubungan antara pelafalan, gerakan dan latihan.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"grimoire","id":5,"intro":"Mantra levitasi memperkenalkan hubungan antara pelafalan, gerakan dan latihan.","note":"Interpretasi editorial: pelajaran yang tampak kecil memperoleh arti baru ketika digunakan dalam situasi mendesak. Mantra ini merupakan unsur fiksi.","related":["mandrake"],"sections":[{"heading":"Dari bulu menuju situasi genting","text":"Di kelas Mantra, murid berlatih mengangkat bulu. Hermione berhasil dengan memperhatikan teknik. Kemudian, dalam pertemuan dengan troll, Ron menerapkan mantra tersebut pada pentungan troll."}],"slug":"wingardium-leviosa","source":{"author":"J. K. Rowling","locator":"Bab 10, Hallowe''en","title":"Harry Potter and the Philosopher''s Stone","type":"book","url":null,"verification":"Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini"},"status":"published","title":"Wingardium Leviosa"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
