INSERT INTO content_sources(content_id,source_id) VALUES(5,5) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(6,'mandrake','herbologi','Mandrake dan suara yang harus diwaspadai','Rumah kaca Hogwarts menyimpan tumbuhan yang menuntut pengetahuan khusus.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"herbologi","id":6,"intro":"Rumah kaca Hogwarts menyimpan tumbuhan yang menuntut pengetahuan khusus.","note":"Pembahasan ini hanya mengenai tumbuhan dalam cerita. Jangan memperlakukan tanaman nyata atau bahan kimia sebagai pengganti ramuan fantasi.","related":["permadani-black"],"sections":[{"heading":"Belajar di rumah kaca","text":"Dalam pelajaran Profesor Sprout, para murid memindahkan Mandrake muda dengan pelindung telinga. Tangis Mandrake dewasa berbahaya, sedangkan tanaman ini juga memiliki peran dalam memulihkan korban yang membatu."}],"slug":"mandrake","source":{"author":"J. K. Rowling","locator":"Bab 6, Gilderoy Lockhart","title":"Harry Potter and the Chamber of Secrets","type":"book","url":null,"verification":"Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini"},"status":"published","title":"Mandrake dan suara yang harus diwaspadai"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(6,'Harry Potter and the Chamber of Secrets','J. K. Rowling','',NULL,'book',NULL,'Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(6,6) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(7,'permadani-black','keluarga-dan-konflik','Keluarga Black: nama, warisan, pilihan','Sebuah permadani memperlihatkan bahwa silsilah juga dapat menjadi pernyataan kekuasaan.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"keluarga-dan-konflik","id":7,"intro":"Sebuah permadani memperlihatkan bahwa silsilah juga dapat menjadi pernyataan kekuasaan.","note":"Interpretasi editorial: pohon keluarga tidak selalu merupakan catatan netral. Penghapusan nama mengungkap siapa yang memiliki kuasa untuk menentukan identitas keluarga.","related":["posisi-quidditch"],"sections":[{"heading":"Siapa yang dianggap bagian keluarga?","text":"Sirius menjelaskan permadani keluarga Black kepada Harry di Grimmauld Place. Nama-nama yang dihapus menunjukkan bagaimana keluarga tersebut memperlakukan anggota yang tidak mengikuti nilai mereka."}],"slug":"permadani-black","source":{"author":"J. K. Rowling","locator":"Bab 6, The Noble and Most Ancient House of Black","title":"Harry Potter and the Order of the Phoenix","type":"book","url":null,"verification":"Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini"},"status":"published","title":"Keluarga Black: nama, warisan, pilihan"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(7,'Harry Potter and the Order of the Phoenix','J. K. Rowling','',NULL,'book',NULL,'Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(7,7) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(8,'posisi-quidditch','quidditch','Tujuh pemain, empat peran','Quidditch membagi perhatian antara mencetak angka, menjaga gawang dan mengejar Snitch.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"quidditch","id":8,"intro":"Quidditch membagi perhatian antara mencetak angka, menjaga gawang dan mengejar Snitch.","note":"Interpretasi editorial: saat mengikuti pertandingan, perhatikan dua alur sekaligus—perebutan Quaffle dan pencarian Snitch. Keduanya berlangsung dalam ruang pertandingan yang sama.","related":["diagon-alley"],"sections":[{"heading":"Memahami alur permainan","text":"Satu tim memiliki tiga Chaser, dua Beater, satu Keeper dan satu Seeker. Chaser menggunakan Quaffle untuk mencetak gol. Keeper menjaga gawang, Beater menangani Bludger, sedangkan Seeker mengejar Golden Snitch."}],"slug":"posisi-quidditch","source":{"author":"J. K. Rowling","locator":"Bab 10, Hallowe''en","title":"Harry Potter and the Philosopher''s Stone","type":"book","url":null,"verification":"Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini"},"status":"published","title":"Tujuh pemain, empat peran"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(8,'Harry Potter and the Philosopher''s Stone','J. K. Rowling','',NULL,'book',NULL,'Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(8,8) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(9,'diagon-alley','lokasi','Diagon Alley: ambang dunia baru','Jalan perbelanjaan sihir mempertemukan kebutuhan sehari-hari dengan rasa takjub.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"lokasi","id":9,"intro":"Jalan perbelanjaan sihir mempertemukan kebutuhan sehari-hari dengan rasa takjub.","note":"Interpretasi editorial: Diagon Alley membangun dunia lewat kegiatan biasa—berbelanja—sehingga hal fantastis terasa menjadi bagian dari kehidupan sehari-hari.","related":["harry-potter"],"sections":[{"heading":"Melalui jalan yang tersembunyi","text":"Dalam kunjungan pertamanya bersama Hagrid, Harry membeli kebutuhan sekolah dan mengenal lembaga serta toko dunia sihir. Gringotts dan Ollivanders menjadi bagian penting dari perjalanan itu."}],"slug":"diagon-alley","source":{"author":"J. K. Rowling","locator":"Bab 5, Diagon Alley","title":"Harry Potter and the Philosopher''s Stone","type":"book","url":null,"verification":"Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini"},"status":"published","title":"Diagon Alley: ambang dunia baru"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(9,'Harry Potter and the Philosopher''s Stone','J. K. Rowling','',NULL,'book',NULL,'Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(9,9) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(10,'harry-potter','tokoh','Harry Potter','Kisah seorang murid yang persahabatan dan pilihannya membentuk perjalanan panjang.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"tokoh","id":10,"intro":"Kisah seorang murid yang persahabatan dan pilihannya membentuk perjalanan panjang.","note":"Interpretasi editorial: membaca Harry hanya sebagai tokoh terkenal akan melewatkan bagaimana keputusan kecil, bantuan teman dan kesediaan mengambil risiko membentuk tindakannya.","related":["boggart"],"sections":[{"heading":"Di luar reputasi","text":"Terbang dan menggunakan Jubah Gaib menjadi bagian dari kehidupan Harry. Hubungannya dengan Ron Weasley, Hermione Granger dan Lord Voldemort menempatkannya dalam jaringan persahabatan sekaligus konflik."}],"slug":"harry-potter","source":{"access_date":"2026-09-14","publisher":"Wizarding World Digital","title":"Harry Potter — referensi resmi","type":"web","url":"https://www.harrypotter.com/fact-file/characters-and-pets/harry-potter","verification":"Diperiksa melalui pencarian web"},"status":"published","title":"Harry Potter"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(10,'Harry Potter — referensi resmi','','Wizarding World Digital','https://www.harrypotter.com/fact-file/characters-and-pets/harry-potter','web','2026-09-14','Diperiksa melalui pencarian web') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(10,10) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(11,'boggart','pertahanan','Boggart: memberi bentuk pada ketakutan','Di kelas Lupin, pertahanan dimulai dengan mengenali apa yang ditakuti.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"pertahanan","id":11,"intro":"Di kelas Lupin, pertahanan dimulai dengan mengenali apa yang ditakuti.","note":"Interpretasi editorial: adegan ini menjadikan ketakutan sesuatu yang dapat diamati dan diubah dalam kerangka cerita. Ini bukan terapi atau nasihat kesehatan mental.","related":["batas-perjalanan-waktu"],"sections":[{"heading":"Riddikulus dan perubahan sudut pandang","text":"Boggart mengambil wujud yang ditakuti orang di hadapannya. Lupin mengajak murid menggunakan Riddikulus sambil membayangkan perubahan yang menggelikan pada wujud tersebut."}],"slug":"boggart","source":{"author":"J. K. Rowling","locator":"Bab 7, The Boggart in the Wardrobe","title":"Harry Potter and the Prisoner of Azkaban","type":"book","url":null,"verification":"Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini"},"status":"published","title":"Boggart: memberi bentuk pada ketakutan"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(11,'Harry Potter and the Prisoner of Azkaban','J. K. Rowling','',NULL,'book',NULL,'Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(11,11) ON CONFLICT DO NOTHING;
INSERT INTO content(id,slug,category,title,intro,document,status,published_at) VALUES(12,'batas-perjalanan-waktu','teori-sihir','Perjalanan waktu dan batas pengetahuan','Time-Turner menantang pemahaman tokoh tentang urutan sebab dan akibat.','{"canon":"Canon utama; catatan dipisahkan sebagai interpretasi editorial","category":"teori-sihir","id":12,"intro":"Time-Turner menantang pemahaman tokoh tentang urutan sebab dan akibat.","note":"Interpretasi editorial: episode ini dapat dibaca sebagai rangkaian peristiwa yang saling terhubung. Model ini tidak boleh dianggap otomatis menjelaskan semua bentuk perjalanan waktu di seluruh karya tambahan.","related":["rahasia-di-balik-sekolah"],"sections":[{"heading":"Melihat kembali sebuah peristiwa","text":"Harry dan Hermione kembali ke rangkaian peristiwa yang sebelumnya mereka alami. Sudut pandang baru mengubah pemahaman Harry terhadap sosok yang ia lihat di tepi danau."}],"slug":"batas-perjalanan-waktu","source":{"author":"J. K. Rowling","locator":"Bab 21, Hermione''s Secret","title":"Harry Potter and the Prisoner of Azkaban","type":"book","url":null,"verification":"Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini"},"status":"published","title":"Perjalanan waktu dan batas pengetahuan"}','published',CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING;
INSERT INTO sources(id,title,author,publisher,url,source_type,access_date,notes) VALUES(12,'Harry Potter and the Prisoner of Azkaban','J. K. Rowling','',NULL,'book',NULL,'Referensi bab; belum diperiksa terhadap salinan buku dalam sesi ini') ON CONFLICT(id) DO NOTHING;
INSERT INTO content_sources(content_id,source_id) VALUES(12,12) ON CONFLICT DO NOTHING;